<?php
namespace Modules\Ran\Reports;
class PurchaseReport extends AbstractRanReport{public function title():string{return 'Purchases';}public function headings():array{return ['Purchase No','Date','Supplier','Status','Subtotal','Tax','Discount','Total','Paid','Balance'];}public function rows(array $f):array{$q=\DB::table('ran_purchases as p')->leftJoin('contacts as c','c.id','=','p.supplier_contact_id')->whereNull('p.deleted_at');$this->filter($q,$f,'p.purchase_date','p');return $q->orderByDesc('p.purchase_date')->get(['p.purchase_no','p.purchase_date',\DB::raw('COALESCE(c.supplier_business_name,c.name) supplier'),'p.status','p.subtotal','p.tax_amount','p.discount_amount','p.total_amount','p.paid_amount','p.balance_amount'])->map(fn($r)=>(array)$r)->all();}public function totals(array $rows):array{return ['Total'=>array_sum(array_column($rows,'total_amount')),'Paid'=>array_sum(array_column($rows,'paid_amount')),'Balance'=>array_sum(array_column($rows,'balance_amount'))];}}
